def decode_string(s):
    stack = []
    num = 0
    str_buf = ""
    for char in s:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char == '[':
            stack.append((num, str_buf))
            num = 0
            str_buf = ""
        elif char == ']':
            num, prev_str = stack.pop()
            str_buf = prev_str + num * str_buf
        else:
            str_buf += char
    return str_buf
```

