def caesar(s, shift):
    result = []
    for char in s:
        if char.isalpha():
            base = ord('a') if char.islower() else ord('A')
            offset = ord(char) - base
            new_offset = (offset + shift) % 26
            new_char = chr(base + new_offset)
            result.append(new_char)
        else:
            result.append(char)
    return ''.join(result)
